/*
 * App state: who is signed in, the firm their login belongs to, biometric lock
 * (Face ID or Touch ID on iPhone, fingerprint or face unlock on Android),
 * appearance, and the firm's brand colors.
 *
 * Every login belongs to one firm (the sponsor or manager that issued it), so
 * signing in opens that firm's account directly. There is no firm list. The
 * device remembers the firm, and a firm's invitation link
 * (shareholderdesk://firm/<id>) sets it before the first sign-in.
 *
 * Demo data: each sample sponsor's workspace is generated by the shared core
 * (the same data the web portal shows). In production, replace `workspaces`
 * and `lookup` with calls to the portal API.
 */
import React, { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { AppState, Platform, useColorScheme } from 'react-native';
import * as LocalAuthentication from 'expo-local-authentication';
import { NS } from '../core';
import { getItem, setItem } from './storage';
import type { Any } from './format';

export type Appearance = 'system' | 'light' | 'dark';
export type Colors = {
  bg: string; surface: string; surface2: string; surface3: string; line: string; lineStrong: string;
  fg: string; fg2: string; fg3: string; brand: string; brandInk: string; brandText: string; brandSoft: string;
  accent: string; accentText: string; chart: string; good: string; warn: string; bad: string;
  markP: string; markA: string; markInk: string; navBg: string; navFg: string; navFgStrong: string; navLine: string;
};
export type Account = { tenantId: string; tenant: Any; investor: Any };
type Session = { tenantId: string; investorId: string; email: string };

type Ctx = {
  ready: boolean;
  session: Session | null;
  locked: boolean;
  tenant: Any | null;
  ws: Any | null;
  investor: Any | null;
  view: Any | null;
  /** The firm this device signs in to: set by an invitation link or the last sign-in. */
  firm: Any | null;
  colors: Colors;
  scheme: 'light' | 'dark';
  appearance: Appearance;
  faceId: boolean;
  biometricsAvailable: boolean;
  /** What this phone calls its biometric unlock, as in "Unlock with …": Face ID, Touch ID, fingerprint, face, or fingerprint or face. */
  biometricLabel: string;
  lookup: (email: string) => Account[];
  signIn: (tenantId: string, investorId: string, email: string) => Promise<void>;
  setFirm: (tenantId: string | null) => Promise<void>;
  signOut: () => Promise<void>;
  unlock: () => Promise<boolean>;
  setAppearance: (a: Appearance) => void;
  setFaceId: (on: boolean) => Promise<boolean>;
  dismissNotice: (id: string) => void;
};

const SessionContext = createContext<Ctx | null>(null);
const LOCK_AFTER_MS = 5 * 60 * 1000;

/** Carrow & Vale's palette (navy and teal), used before the investor's firm is known. */
const NEUTRAL = { colors: { primary: '#0F2742', accent: '#1F7A8C' }, nav: 'light' };

function toColors(tenantLike: Any, scheme: 'light' | 'dark'): Colors {
  const tk = NS.brand.derive(tenantLike);
  const T = scheme === 'dark' ? tk.dark : tk.light;
  const dark = scheme === 'dark';
  return {
    bg: T.surface,
    surface: T.surface,
    surface2: T['surface-2'],
    surface3: T['surface-3'],
    line: T.line,
    lineStrong: T['line-strong'],
    fg: T.fg,
    fg2: T['fg-2'],
    fg3: T['fg-3'],
    brand: T.brand,
    brandInk: T['brand-ink'],
    brandText: T['brand-text'],
    brandSoft: T['brand-soft'],
    accent: T.accent,
    accentText: T['accent-text'],
    chart: T['chart-1'],
    good: dark ? '#5CC28D' : '#1B6E45',
    warn: dark ? '#E6B24F' : '#8A5300',
    bad: dark ? '#F2867D' : '#B3261E',
    markP: T['mark-p'],
    markA: T['mark-a'],
    markInk: T['mark-ink'],
    navBg: T['nav-bg'],
    navFg: T['nav-fg'],
    navFgStrong: T['nav-fg-strong'],
    navLine: T['nav-line']
  };
}

export function SessionProvider({ children }: { children: React.ReactNode }) {
  // One workspace per sample sponsor, generated by the shared core.
  const workspaces = useMemo<Record<string, Any>>(() => {
    const out: Record<string, Any> = {};
    NS.TENANTS.forEach((t: Any) => (out[t.id] = NS.seedWorkspace(t)));
    return out;
  }, []);

  const [ready, setReady] = useState(false);
  const [session, setSession] = useState<Session | null>(null);
  const [firmId, setFirmId] = useState<string | null>(null);
  const [locked, setLocked] = useState(false);
  const [appearance, setAppearanceState] = useState<Appearance>('system');
  const [faceId, setFaceIdState] = useState(false);
  const [biometricsAvailable, setBiometricsAvailable] = useState(false);
  const [biometricLabel, setBiometricLabel] = useState(Platform.OS === 'ios' ? 'Face ID' : 'fingerprint');
  const [rev, setRev] = useState(0);
  const backgroundedAt = useRef<number | null>(null);
  const system = useColorScheme();
  const scheme: 'light' | 'dark' = appearance === 'system' ? (system === 'dark' ? 'dark' : 'light') : appearance;

  const lookup = useCallback(
    (email: string): Account[] => {
      const e = email.trim().toLowerCase();
      if (!e) return [];
      return Object.keys(workspaces)
        .map((id) => {
          const inv = workspaces[id].investors.find((i: Any) => String(i.email).toLowerCase() === e);
          return inv ? { tenantId: id, tenant: workspaces[id].tenant, investor: inv } : null;
        })
        .filter(Boolean) as Account[];
    },
    [workspaces]
  );

  const applyDismissed = useCallback(
    async (tenantId: string, investorId: string) => {
      const raw = await getItem(`dismissed.${tenantId}.${investorId}`);
      const inv = workspaces[tenantId]?.investors.find((i: Any) => i.id === investorId);
      if (inv && raw) inv.noticesRead = JSON.parse(raw);
    },
    [workspaces]
  );

  // Restore the saved session and preferences.
  useEffect(() => {
    (async () => {
      const [s, a, f, fm] = await Promise.all([getItem('session'), getItem('appearance'), getItem('faceId'), getItem('firm')]);
      if (fm && workspaces[fm]) setFirmId(fm);
      if (a === 'light' || a === 'dark' || a === 'system') setAppearanceState(a);
      let canBio = false;
      if (Platform.OS !== 'web') {
        try {
          canBio = (await LocalAuthentication.hasHardwareAsync()) && (await LocalAuthentication.isEnrolledAsync());
          setBiometricLabel(labelFor(await LocalAuthentication.supportedAuthenticationTypesAsync()));
        } catch {
          canBio = false;
        }
      }
      setBiometricsAvailable(canBio);
      const useFace = f === '1' && canBio;
      setFaceIdState(useFace);
      if (s) {
        try {
          const parsed = JSON.parse(s) as Session;
          if (workspaces[parsed.tenantId]?.investors.some((i: Any) => i.id === parsed.investorId)) {
            await applyDismissed(parsed.tenantId, parsed.investorId);
            setSession(parsed);
            if (useFace) setLocked(true);
          }
        } catch {
          /* ignore a damaged saved session */
        }
      }
      setReady(true);
    })();
  }, [workspaces, applyDismissed]);

  // Lock again after five minutes in the background when biometric unlock is on.
  useEffect(() => {
    const sub = AppState.addEventListener('change', (st) => {
      if (st === 'background') backgroundedAt.current = Date.now();
      if (st === 'active' && backgroundedAt.current && faceId && session && Date.now() - backgroundedAt.current > LOCK_AFTER_MS) setLocked(true);
    });
    return () => sub.remove();
  }, [faceId, session]);

  const signIn = useCallback(
    async (tenantId: string, investorId: string, email: string) => {
      const s = { tenantId, investorId, email };
      await applyDismissed(tenantId, investorId);
      await Promise.all([setItem('session', JSON.stringify(s)), setItem('firm', tenantId)]);
      setFirmId(tenantId);
      setSession(s);
      setLocked(false);
    },
    [applyDismissed]
  );
  const setFirm = useCallback(
    async (tenantId: string | null) => {
      const id = tenantId && workspaces[tenantId] ? tenantId : null;
      setFirmId(id);
      await setItem('firm', id);
    },
    [workspaces]
  );
  const signOut = useCallback(async () => {
    await setItem('session', null);
    setSession(null);
    setLocked(false);
  }, []);
  const unlock = useCallback(async () => {
    try {
      const r = await LocalAuthentication.authenticateAsync({ promptMessage: 'Unlock Shareholder Desk', cancelLabel: 'Cancel' });
      if (r.success) setLocked(false);
      return r.success;
    } catch {
      return false;
    }
  }, []);
  const setAppearance = useCallback((a: Appearance) => {
    setAppearanceState(a);
    setItem('appearance', a);
  }, []);
  const setFaceId = useCallback(async (on: boolean) => {
    if (!on) {
      setFaceIdState(false);
      await setItem('faceId', '0');
      return true;
    }
    try {
      const r = await LocalAuthentication.authenticateAsync({ promptMessage: 'Turn on biometric unlock for Shareholder Desk', cancelLabel: 'Cancel' });
      if (!r.success) return false;
      setFaceIdState(true);
      await setItem('faceId', '1');
      return true;
    } catch {
      return false;
    }
  }, []);

  const ws = session ? workspaces[session.tenantId] : null;
  const tenant = ws ? ws.tenant : null;
  const investor = ws && session ? ws.investors.find((i: Any) => i.id === session.investorId) || null : null;
  // `rev` changes when the investor's data changes (for example a dismissed notice).
  const view = useMemo(() => (ws && investor ? NS.investorView(ws, investor.id) : null), [ws, investor, rev]); // eslint-disable-line react-hooks/exhaustive-deps
  const firm = firmId ? workspaces[firmId].tenant : null;
  const colors = useMemo(() => toColors(tenant || NEUTRAL, scheme), [tenant, scheme]);

  const dismissNotice = useCallback(
    (id: string) => {
      if (!investor || !session) return;
      investor.noticesRead = (investor.noticesRead || []).concat([id]);
      setItem(`dismissed.${session.tenantId}.${investor.id}`, JSON.stringify(investor.noticesRead));
      setRev((r) => r + 1);
    },
    [investor, session]
  );

  const value: Ctx = {
    ready, session, locked, tenant, ws, investor, view, firm, colors, scheme, appearance, faceId, biometricsAvailable, biometricLabel,
    lookup, signIn, setFirm, signOut, unlock, setAppearance, setFaceId, dismissNotice
  };
  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>;
}

function labelFor(types: LocalAuthentication.AuthenticationType[]): string {
  const face = types.includes(LocalAuthentication.AuthenticationType.FACIAL_RECOGNITION);
  const finger = types.includes(LocalAuthentication.AuthenticationType.FINGERPRINT);
  if (Platform.OS === 'ios') return face ? 'Face ID' : 'Touch ID';
  if (face && finger) return 'fingerprint or face';
  return face ? 'face' : 'fingerprint';
}

export function useSession(): Ctx {
  const c = useContext(SessionContext);
  if (!c) throw new Error('useSession must be used inside SessionProvider');
  return c;
}
export const useColors = () => useSession().colors;
